import { PlaneGeometry, MeshBasicNodeMaterial, Mesh, Object3D, Color, Texture } from 'three/webgpu';
import { gsap } from 'gsap';

export default function createNode(config, ctx) {
  const group = new Object3D();

  // Build textured plane for primary CTA
  const geometry = new PlaneGeometry(4.5, 1.8);

  const material = new MeshBasicNodeMaterial({
    color: new Color('#0b0b10'),
    transparent: true,
    opacity: 0.92,
  });

  const mesh = new Mesh(geometry, material);
  mesh.position.set(0, 0, 0);
  mesh.userData.elementType = 'primary-cta';

  // Load texture from config
  if (config.imageUrl) {
    ctx.textureLoader.loadTexture(config.imageUrl).then((texture) => {
      texture.colorSpace = 'srgb';
      material.map = texture;
      material.needsUpdate = true;

      // Entrance animation - fade up with weighted settle
      mesh.material.opacity = 0;
      mesh.position.y = 0.4;

      const tl = gsap.timeline({ delay: 0.3 });
      tl.to(mesh.position, {
        y: 0,
        duration: 0.7,
        ease: 'power3.out'
      });
      tl.to(mesh.material, {
        opacity: 0.92,
        duration: 0.5,
        ease: 'power2.out'
      }, '<');
      tl.to(mesh.scale, {
        x: 1,
        y: 1,
        duration: 0.9,
        ease: 'power4.out',
        onComplete: () => {
          // Small settle overshoot
          gsap.to(mesh.scale, {
            x: 1,
            y: 1,
            duration: 0.3,
            ease: 'power4.out'
          });
        }
      }, '-=0.4');
    });
  }

  // Engineered gradient surface - vertical gradient from surface to paper
  // Create a subtle gradient plane behind the CTA for depth
  const gradientGeo = new PlaneGeometry(5.2, 2.4);
  const gradientMat = new MeshBasicNodeMaterial({
    color: new Color('#16161d'),
    transparent: true,
    opacity: 0.15,
  });
  const gradientMesh = new Mesh(gradientGeo, gradientMat);
  gradientMesh.position.z = -0.05;
  mesh.add(gradientMesh);

  // Add subtle grain overlay
  const grainGeo = new PlaneGeometry(4.5, 1.8);
  const grainMat = new MeshBasicNodeMaterial({
    color: new Color('#e8ecf2'),
    transparent: true,
    opacity: 0.02,
  });
  const grainMesh = new Mesh(grainGeo, grainMat);
  grainMesh.position.z = 0.01;
  mesh.add(grainMesh);

  group.add(mesh);

  // Apply scene position
  group.position.set(0, -2.85, 0.2);

  // Event handlers
  group.userData.handlers = {
    click: () => {
      ctx.emit('navigate', { to: 'hub-pricing' });
    },
    hover: () => {
      gsap.to(mesh.scale, {
        x: 1.02,
        y: 1.02,
        duration: 0.3,
        ease: 'power2.out'
      });
    },
    hoverEnd: () => {
      gsap.to(mesh.scale, {
        x: 1,
        y: 1,
        duration: 0.3,
        ease: 'power2.out'
      });
    }
  };

  // Cleanup
  group.userData.cleanup = () => {
    gsap.killTweensOf(mesh.position);
    gsap.killTweensOf(mesh.scale);
    gsap.killTweensOf(mesh.material);
    geometry.dispose();
    material.dispose();
    gradientGeo.dispose();
    gradientMat.dispose();
    grainGeo.dispose();
    grainMat.dispose();
  };

  return group;
}
